// ─── Pick Product & Build Prompts ───────────────────────────
// Inputs: customer data, products list, webhook body

const webhook = $('Webhook').first().json.body;
const customer = $('Get Customer').first().json;
const products = $('Get Products').all().map(i => i.json);

// --- Determine product ---
let product;
if (webhook.product_name) {
  // Explicit product requested (campaign/telegram)
  product = products.find(p => p.Product_Name === webhook.product_name) || products[0];
} else {
  // Rotation: pick the one with oldest Last_Featured_Date (null = never featured = first)
  product = products[0]; // Already sorted ASC by Last_Featured_Date
}

if (!product) {
  throw new Error(`No active products for customer ${webhook.customer_id}`);
}

// --- Get customer prompts (from lookups) ---
const promptText = Array.isArray(customer.Prompt_Text) ? customer.Prompt_Text[0] : (customer.Prompt_Text || '');
const promptVisual = Array.isArray(customer.Prompt_Visual) ? customer.Prompt_Visual[0] : (customer.Prompt_Visual || '');
const promptVideo = Array.isArray(customer.Prompt_Visual_to_Video) ? customer.Prompt_Visual_to_Video[0] : (customer.Prompt_Visual_to_Video || '');

// --- Determine format ---
const format = webhook.format || 'image'; // 'image' or 'video'

// --- Build Claude prompt for text generation ---
const brief = webhook.brief || '';
const campaignContext = brief ? `\n\nBrief spécifique : ${brief}` : '';

const claudeSystemPrompt = promptText || `Tu es un Social Media Manager expert. Crée un post engageant pour ${customer.Customer_Name}.`;

const claudeUserPrompt = `Crée un post pour le produit suivant :

Produit : ${product.Product_Name}
Description : ${product.Description || 'N/A'}
Prix : ${product.Price || 'N/A'}

Client : ${customer.Customer_Name}
Secteur : ${customer.Customer_Market || 'N/A'}
Cible : ${customer.Target_Personna || 'N/A'}
CTA : ${customer.CTA || 'N/A'}
Ton : ${customer.Mood || 'N/A'}${campaignContext}

Format : ${format === 'video' ? 'Reel/Story/TikTok (court, punchy, 15s max de lecture)' : 'Post Instagram (engageant, avec hashtags)'}

Réponds UNIQUEMENT en JSON :
{
  "post_text": "le texte du post complet avec emojis et hashtags",
  "prompt_visual": "prompt EN ANGLAIS pour générer l'image food photography, style: ${customer.Visual_type || 'photo réaliste'}, couleurs: ${customer.Color_Set || 'warm tones'}",
  "prompt_video": "prompt EN ANGLAIS pour générer une vidéo 8s de type story/reel, style: ${customer.Visual_to_Video_type || customer.Visual_type || 'dynamic food video'}"
}`;

return [{
  json: {
    // Pass through for later nodes
    customer_id: webhook.customer_id,
    customer_name: customer.Customer_Name,
    customer_record_id: customer.id,
    product_name: product.Product_Name,
    product_record_id: product.id,
    format: format,
    source: webhook.source || 'Rotation',
    campaign_id: webhook.campaign_id || '',
    slot_time: webhook.slot_time || '',
    blotato_client_id: customer.Blotato_Client_ID || '',
    // Claude prompts
    claude_system: claudeSystemPrompt,
    claude_user: claudeUserPrompt,
    // Visual prompts (fallback if Claude fails)
    fallback_prompt_visual: promptVisual,
    fallback_prompt_video: promptVideo
  }
}];

// ─── Parse Claude Response ──────────────────────────────────
const prev = $('Pick Product & Build Prompts').first().json;
const claudeOutput = $input.first().json;

// Native Anthropic node returns content[0].text
const responseText = claudeOutput.content?.[0]?.text || claudeOutput.text || '';

// Parse JSON from response
let parsed;
try {
  const jsonMatch = responseText.match(/\{[\s\S]*\}/);
  parsed = JSON.parse(jsonMatch[0]);
} catch (e) {
  parsed = {
    post_text: responseText.substring(0, 500),
    prompt_visual: prev.fallback_prompt_visual,
    prompt_video: prev.fallback_prompt_video
  };
}

return [{
  json: {
    ...prev,
    post_text: parsed.post_text || '',
    prompt_visual: parsed.prompt_visual || prev.fallback_prompt_visual,
    prompt_video: parsed.prompt_video || prev.fallback_prompt_video,
    format: prev.format
  }
}];

// ─── Build Content_Pipeline Record ──────────────────────────
const data = $('Parse Claude Response').first().json;
const mediaItem = $input.first();

// Check if we have a video URL or binary image
const hasVideoUrl = data.format === 'video' && mediaItem.json?.url;
const hasBinaryMedia = !!mediaItem.binary?.generated_media;

const now = new Date().toISOString();

return [{
  json: {
    // Content_Pipeline fields
    Customer_Name: data.customer_name,
    Customer_ID: data.customer_id,
    Status: 'Draft',
    Platform: data.format === 'video' ? 'TikTok' : 'Instagram',
    Post: data.post_text,
    Prompt_Visual: data.prompt_visual,
    Prompt_Video: data.prompt_video,
    Product_Name: data.product_name,
    Campaign_ID: data.campaign_id,
    Source: data.source,
    Video_Status: data.format === 'video' ? 'Ready' : '',
    PublishAt: data.slot_time || '',
    // Media URL (for video) or will use binary upload
    URL_Visual: hasVideoUrl ? mediaItem.json.url : '',
    // Pass-through for subsequent nodes
    _product_record_id: data.product_record_id,
    _customer_record_id: data.customer_record_id,
    _format: data.format,
    _blotato_client_id: data.blotato_client_id,
    _has_binary: hasBinaryMedia
  },
  // Preserve binary data if present
  binary: mediaItem.binary || {}
}];

// Parse QA response from Claude
const claudeOutput = $input.first().json;
const responseText = claudeOutput.content?.[0]?.text || claudeOutput.text || '';
const pipelineId = $('Create Content_Pipeline').first().json.id;

let parsed;
try {
  const jsonMatch = responseText.match(/```(?:json)?\s*([\s\S]*?)```/);
  parsed = JSON.parse((jsonMatch ? jsonMatch[1] : responseText).trim());
} catch (e) {
  parsed = { verdict: 'WARN', score: 5.0, new_status: 'Prêt à publier', feedback: 'QA parse error: ' + e.message, suggestions: [], alternative_post: '' };
}

parsed.post_id = pipelineId;

// Validate verdict
if (!['PASS', 'WARN', 'FAIL'].includes(parsed.verdict)) parsed.verdict = 'WARN';
if (typeof parsed.score !== 'number') parsed.score = 5.0;
if (!['Prêt à publier', 'Edité'].includes(parsed.new_status)) {
  parsed.new_status = parsed.score >= 5.0 ? 'Prêt à publier' : 'Edité';
}

return [{ json: parsed }];

